const a = [...input.values];
viz.array('a', a);
viz.step({ explanation: `Ausgangslage: ${a.join(', ')}` });
function quick(lo, hi) {
if (lo > hi) return;
if (lo === hi) { viz.highlight('a', { indices: [lo, lo] }, 'sorted'); viz.step({ explanation: `${a[lo]} steht allein und ist sortiert.` }); return; }
const pivot = a[hi];
viz.pointer('a', 'pivot', hi);
viz.highlight('a', { indices: [hi, hi] }, 'active');
viz.step({ explanation: `Pivot ist ${pivot} (Index ${hi}) im Bereich ${lo} bis ${hi}.` });
let i = lo;
for (let j = lo; j < hi; j++) {
viz.pointer('a', 'i', i);
viz.pointer('a', 'j', j);
viz.highlight('a', { indices: [j, hi] }, 'compare');
const vj = a[j];
if (vj < pivot) {
const vi = a[i];
if (i !== j) { a[i] = vj; a[j] = vi; viz.swap('a', i, j); }
i++;
viz.step({ explanation: `${vj} < ${pivot}: gehört in den linken Bereich.` });
} else {
viz.step({ explanation: `${vj} ≥ ${pivot}: bleibt im rechten Bereich.` });
}
}
if (i !== hi) { const t = a[i]; a[i] = a[hi]; a[hi] = t; viz.swap('a', i, hi); }
viz.highlight('a', { indices: [i, i] }, 'sorted');
viz.step({ explanation: `Pivot ${pivot} steht jetzt an Index ${i}.` });
quick(lo, i - 1);
quick(i + 1, hi);
}
quick(0, a.length - 1);
viz.highlight('a', { range: [0, a.length - 1] }, 'sorted');
viz.step({ explanation: `Fertig sortiert: ${a.join(', ')}` });

const a = [...input.values];
const n = a.length;
viz.array('a', a);
viz.step({ explanation: `Ausgangslage: ${a.join(', ')}. Ich baue den Max-Heap von unten nach oben auf.` });
function siftDown(start, end) {
  let i = start;
  while (true) {
    let largest = i;
    const l = 2 * i + 1;
    const r = 2 * i + 2;
    if (l < end) {
      viz.highlight('a', { indices: [i, l] }, 'compare');
      if (a[l] > a[largest]) largest = l;
    }
    if (r < end) {
      viz.highlight('a', { indices: [largest, r] }, 'compare');
      if (a[r] > a[largest]) largest = r;
    }
    if (largest === i) {
      viz.step({ explanation: `${a[i]} ist größer als seine Kinder, es bleibt stehen.` });
      break;
    }
    viz.step({ explanation: `${a[i]} ist kleiner als ${a[largest]}, also tauschen.` });
    [a[i], a[largest]] = [a[largest], a[i]];
    viz.swap('a', i, largest);
    viz.step({ explanation: `Getauscht: ${a.join(', ')}` });
    i = largest;
  }
}
for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
  viz.pointer('a', 'i', i);
  viz.step({ explanation: `Knoten an Index ${i} (Wert ${a[i]}) wird eingesickert.` });
  siftDown(i, n);
}
viz.step({ explanation: `Max-Heap fertig: ${a.join(', ')}` });

const a = [...input.values];
viz.array('a', a);
viz.step({ explanation: `Ausgangslage: ${a.join(', ')}` });
for (let i = 0; i < a.length - 1; i++) {
  let min = i;
  viz.pointer('a', 'min', min);
  viz.step({ explanation: `Suche das Minimum ab Position ${i}, vorläufig ${a[min]}.` });
  for (let j = i + 1; j < a.length; j++) {
    viz.highlight('a', { indices: [min, j] }, 'compare');
    if (a[j] < a[min]) {
      min = j;
      viz.pointer('a', 'min', min);
      viz.step({ explanation: `${a[j]} < ${a[min]}: neues Minimum ${a[min]} an Position ${min}.` });
    } else {
      viz.step({ explanation: `${a[j]} ist nicht kleiner als ${a[min]}.` });
    }
  }
  if (min !== i) {
    [a[i], a[min]] = [a[min], a[i]];
    viz.swap('a', i, min);
    viz.highlight('a', { range: [0, i] }, 'sorted');
    viz.step({ explanation: `Minimum ${a[i]} wird an Position ${i} getauscht: ${a.join(', ')}` });
  } else {
    viz.highlight('a', { range: [0, i] }, 'sorted');
    viz.step({ explanation: `${a[i]} steht bereits an Position ${i}.` });
  }
}
viz.highlight('a', { range: [0, a.length - 1] }, 'sorted');
viz.step({ explanation: `Fertig sortiert: ${a.join(', ')}` });

const a = [...input.values];
viz.array('a', a);
viz.step({ explanation: `Ausgangslage: ${a.join(', ')}` });
for (let end = a.length - 1; end > 0; end--) {
  for (let i = 0; i < end; i++) {
    viz.highlight('a', { indices: [i, i + 1] }, 'compare');
    if (a[i] > a[i + 1]) {
      viz.step({ explanation: `${a[i]} > ${a[i + 1]}, also tauschen.` });
      [a[i], a[i + 1]] = [a[i + 1], a[i]];
      viz.swap('a', i, i + 1);
      viz.highlight('a', { indices: [i, i + 1] }, 'swap');
      viz.step({ explanation: `Getauscht: ${a.join(', ')}` });
    } else {
      viz.step({ explanation: `${a[i]} ≤ ${a[i + 1]}, kein Tausch.` });
    }
  }
  viz.highlight('a', { range: [end, a.length - 1] }, 'sorted');
  viz.step({ explanation: `${a[end]} steht an seinem endgültigen Platz.` });
}
viz.highlight('a', { range: [0, a.length - 1] }, 'sorted');
viz.step({ explanation: `Fertig sortiert: ${a.join(', ')}` });

const a = [...input.values];
viz.array('a', a);
viz.step({ explanation: `Ausgangslage: ${a.join(', ')}` });
for (let i = 1; i < a.length; i++) {
  let j = i;
  viz.pointer('a', 'key', i);
  viz.step({ explanation: `Füge ${a[i]} in den sortierten Teil links davon ein.` });
  while (j > 0 && a[j - 1] > a[j]) {
    viz.highlight('a', { indices: [j - 1, j] }, 'compare');
    viz.step({ explanation: `${a[j - 1]} > ${a[j]}, also tauschen.` });
    [a[j - 1], a[j]] = [a[j], a[j - 1]];
    viz.swap('a', j - 1, j);
    j--;
    viz.pointer('a', 'key', j);
    viz.step({ explanation: `Getauscht: ${a.join(', ')}` });
  }
  if (j > 0) {
    viz.highlight('a', { indices: [j - 1, j] }, 'compare');
    viz.step({ explanation: `${a[j - 1]} ≤ ${a[j]}, Einfügeposition gefunden.` });
  }
  viz.highlight('a', { range: [0, i] }, 'sorted');
  viz.step({ explanation: `Die ersten ${i + 1} Elemente sind sortiert: ${a.slice(0, i + 1).join(', ')}` });
}
viz.highlight('a', { range: [0, a.length - 1] }, 'sorted');
viz.step({ explanation: `Fertig sortiert: ${a.join(', ')}` });

const a = [...input.values];
viz.array('a', a);
viz.step({ explanation: `Ausgangslage: ${a.join(', ')}` });
for (let end = a.length - 1; end > 0; end--) {
  for (let i = 0; i < end; i++) {
    viz.highlight('a', { indices: [i, i + 1] }, 'compare');
    if (a[i] > a[i + 1]) {
      viz.step({ explanation: `${a[i]} kommt alphabetisch nach ${a[i + 1]}, also tauschen.` });
      [a[i], a[i + 1]] = [a[i + 1], a[i]];
      viz.swap('a', i, i + 1);
      viz.highlight('a', { indices: [i, i + 1] }, 'swap');
      viz.step({ explanation: `Getauscht: ${a.join(', ')}` });
    } else {
      viz.step({ explanation: `${a[i]} steht alphabetisch vor ${a[i + 1]}, kein Tausch.` });
    }
  }
  viz.highlight('a', { range: [end, a.length - 1] }, 'sorted');
  viz.step({ explanation: `${a[end]} steht an seinem endgültigen Platz.` });
}
viz.highlight('a', { range: [0, a.length - 1] }, 'sorted');
viz.step({ explanation: `Fertig sortiert: ${a.join(', ')}` });

const a = [...input.values];
const target = input.target;
viz.array('a', a);
viz.scalar('target', target);
viz.step({ explanation: `Ausgangslage: Suche ${target} in ${a.join(', ')}` });
let lo = 0;
let hi = a.length - 1;
let found = -1;
while (lo <= hi) {
  const mid = Math.floor((lo + hi) / 2);
  viz.highlight('a', { range: [lo, hi] }, 'range');
  viz.pointer('a', 'mid', mid);
  viz.highlight('a', { indices: [mid, mid] }, 'compare');
  viz.step({ explanation: `Mitte ist Index ${mid} mit Wert ${a[mid]}.` });
  if (a[mid] === target) {
    found = mid;
    viz.step({ explanation: `${a[mid]} ist gleich ${target}, Treffer bei Index ${mid}.` });
    break;
  } else if (a[mid] < target) {
    viz.step({ explanation: `${a[mid]} < ${target}, also die linke Hälfte verwerfen.` });
    lo = mid + 1;
  } else {
    viz.step({ explanation: `${a[mid]} > ${target}, also die rechte Hälfte verwerfen.` });
    hi = mid - 1;
  }
}
if (found < 0) {
  viz.step({ explanation: `${target} ist nicht im Array enthalten.` });
} else {
  viz.step({ explanation: `Ergebnis: ${target} steht an Index ${found}.` });
}

const p = input.params;
const n = p.n !== undefined ? p.n : p.find((q) => q.name === 'n').value;
viz.scalar('a', 0);
viz.scalar('b', 1);
viz.scalar('i', 0);
viz.step({ explanation: 'Ausgangslage: F(0) = 0, F(1) = 1, gesucht ist F(' + n + ').' });
let a = 0;
let b = 1;
for (let i = 2; i <= n; i++) {
  const c = a + b;
  a = b;
  b = c;
  viz.setScalar('a', a);
  viz.setScalar('b', b);
  viz.setScalar('i', i);
  viz.step({ explanation: 'Schritt ' + i + ': F(' + i + ') = ' + b });
}
const result = n === 0 ? 0 : b;
viz.step({ explanation: 'Ergebnis: F(' + n + ') = ' + result });

const { nodes, edges, directed, start } = input;
viz.graph('g', { nodes, edges, directed });
const dist = new Map();
const prev = new Map();
const done = new Set();
for (const n of nodes) dist.set(n.id, Infinity);
dist.set(start, 0);
const fmt = (d) => (d === Infinity ? '∞' : String(d));
const summary = () => nodes.map((n) => `${n.id}=${fmt(dist.get(n.id))}`).join(', ');
viz.nodeState('g', start, 'frontier');
viz.step({ explanation: `Ausgangslage: ${start} hat Distanz 0, alle anderen ∞.` });
while (true) {
  let cur = null;
  for (const n of nodes) {
    if (done.has(n.id) || dist.get(n.id) === Infinity) continue;
    if (cur === null || dist.get(n.id) < dist.get(cur)) cur = n.id;
  }
  if (cur === null) break;
  viz.nodeState('g', cur, 'active');
  viz.step({ explanation: `Wähle ${cur} mit kleinster Distanz ${dist.get(cur)}.` });
  for (const e of edges) {
    let other = null;
    if (e.from === cur) other = e.to;
    else if (!directed && e.to === cur) other = e.from;
    if (other === null || done.has(other)) continue;
    const w = e.weight ?? 1;
    const nd = dist.get(cur) + w;
    if (nd < dist.get(other)) {
      const old = prev.get(other);
      if (old !== undefined) viz.edgeState('g', old, 'default');
      dist.set(other, nd);
      prev.set(other, e.id);
      viz.edgeState('g', e.id, 'tree');
      viz.nodeState('g', other, 'frontier');
      viz.step({ explanation: `Über ${cur}: ${other} wird ${nd} (Kante ${e.id}, Gewicht ${w}).` });
    } else {
      viz.edgeState('g', e.id, 'rejected');
      viz.step({ explanation: `Über ${cur} wären es ${nd} für ${other}, nicht kürzer als ${fmt(dist.get(other))}.` });
    }
  }
  done.add(cur);
  viz.nodeState('g', cur, 'visited');
  viz.step({ explanation: `${cur} ist fertig. Stand: ${summary()}` });
}
viz.step({ explanation: `Fertig. Kürzeste Distanzen von ${start}: ${summary()}` });
